/**
 * Opaque marker for a calculated-field expression pulled from the
 * server. Wraps the server's stored expression string in a
 * `CalculationExpression` brand so it round-trips byte-stable through
 * `.deploy()` without any TS-side parsing.
 *
 * Why this exists (and why it isn't on the public `calc` namespace):
 *
 * Calculated expressions are stored on the server as a single string
 * (the raw text the ANTLR parser accepts). The platform's parser also
 * NORMALIZES expressions on conversion — `"Quantity" / "Threshold"`
 * becomes something like `division(...,  nullIf(cast(..., DECIMAL), 0))`
 * server-side, so the stored text after a deploy may not match what
 * the author wrote in the EDK DSL. Parsing it back into typed AST
 * form would require both a TS port of the grammar AND an
 * un-normalization pass — neither of which the EDK ships today.
 *
 * The marker sidesteps the problem: on pull, the deserializer wraps
 * the server's stored string in `__pulledExpression(...)`. On
 * re-deploy, the serializer reads `toCalcString()` and emits the
 * exact same string. The server gets back what it stored.
 *
 * **Edit contract.** When an agent edits a pulled file:
 *   - **Unchanged expression** — leave the `__pulledExpression(...)`
 *     call alone. Re-deploy emits the same string, no semantic change.
 *   - **Changed expression** — REPLACE THE ENTIRE CALL with a typed
 *     `calc.*` expression (e.g. `calc.if(calc.gt(f.x, 10), 'hi', 'lo')`).
 *     The typed DSL gives the agent compile-time validation of field
 *     refs, function names, and argument types. Tweaking the inner
 *     string directly bypasses TypeScript and reintroduces the
 *     hallucination surface the typed DSL exists to eliminate.
 *
 * **Why this module isn't in `src/aspects/index.ts`.** Public-API
 * autocomplete is the path an authoring agent discovers the EDK
 * through. Surfacing `__pulledExpression` there would invite agents to
 * use it as a generic "raw string expression" escape hatch, which
 * defeats the typed DSL. Pulled files import this symbol via the
 * deep path `../../aspects/deserializer/pulled-expression.js` — the
 * unusual import signals "pull-printer-emitted; not for hand-authoring."
 */
import type { CalculationExpression } from "../../../core/types/app.js";
import type { Expr, ExprType } from "../../field/calc/types.js";
/**
 * Wrap the server-stored expression string as an opaque
 * `CalculationExpression`. The only call site is the pull printer
 * (`print-aspect.ts`); agents authoring new fields use the typed
 * `calc.*` builder instead.
 *
 * Naming uses the `__` prefix that other pull-printer-emitted runtime
 * guards on this codebase use (`__pulledType`, `__pulledValueIds`) —
 * signals "this came from the pull printer; the runtime treats it
 * specially."
 */
export declare function __pulledExpression(serverText: string): CalculationExpression;
/**
 * Pull-only fidelity bridge for server-normalized calculation grammar.
 * Hand-authored calculations should use the typed `calc.*` DSL instead.
 */
export declare function preservePulledCalculation<T extends ExprType>(serverText: string, resultType: T): Expr<T, "single", "record">;
